import * as THREE from 'three';
export const defaultPhotoLayout=()=>({x:0,y:0,scale:1,rotation:0,opacity:1});
// Compose in wall coordinates, preserving the original image's proportions.
export function renderPhoto(sector,definition){if(!sector.photo)return;const layout=sector.photoLayout||defaultPhotoLayout(),image=sector.photo.image;if(!sector.photoCanvas){sector.photoCanvas=document.createElement('canvas');sector.photoMap=new THREE.CanvasTexture(sector.photoCanvas);sector.photoMap.colorSpace=THREE.SRGBColorSpace;}
 const c=sector.photoCanvas,ratio=sector.width/definition.h,w=Math.round(ratio>=1?1600:1600*ratio),h=Math.round(ratio>=1?1600/ratio:1600);if(c.width!==w||c.height!==h){c.width=w;c.height=h;}
 const ctx=c.getContext('2d');ctx.clearRect(0,0,w,h);ctx.fillStyle=definition.color;ctx.fillRect(0,0,w,h);const fit=Math.min(w/image.width,h/image.height)*layout.scale;ctx.save();ctx.translate(w*(.5+layout.x),h*(.5-layout.y));ctx.rotate(-THREE.MathUtils.degToRad(layout.rotation));ctx.globalAlpha=layout.opacity;ctx.drawImage(image,-image.width*fit/2,-image.height*fit/2,image.width*fit,image.height*fit);ctx.restore();sector.photoMap.needsUpdate=true;sector.wall.material.map=sector.photoMap;sector.wall.material.color.set('#ffffff');sector.wall.material.needsUpdate=true;
}
export function removePhoto(sector,definition){sector.photo?.dispose();sector.photoMap?.dispose();sector.photo=null;sector.photoMap=null;sector.photoCanvas=null;sector.photoLayout=defaultPhotoLayout();sector.wall.material.map=null;sector.wall.material.color.set(definition.color);sector.wall.material.needsUpdate=true;}
export function createPhotoEditor({camera,renderer,controls,sectors,walls,defs,getSector,beforeChange,onActivate}){
 let active=false,drag=null;const canvas=renderer.domElement,ray=new THREE.Raycaster(),pointer=new THREE.Vector2(),button=document.querySelector('#movePhoto');
 const hint=document.createElement('div');hint.id='photoMoveHint';hint.hidden=true;hint.textContent='Drag the photo to align it · Esc to finish';document.body.append(hint);
 function point(e,si){const rect=canvas.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);ray.setFromCamera(pointer,camera);const face=sectors[si].face;face.updateWorldMatrix(true,false);const normal=new THREE.Vector3(0,0,1).transformDirection(face.matrixWorld),origin=face.localToWorld(new THREE.Vector3(0,0,.126));const p=ray.ray.intersectPlane(new THREE.Plane().setFromNormalAndCoplanarPoint(normal,origin),new THREE.Vector3());return p?face.worldToLocal(p):null;}
 function finish(cancel=false){if(!drag)return;const d=drag;drag=null;if(cancel){sectors[d.si].photoLayout=d.layout;renderPhoto(sectors[d.si],defs[d.si]);sync();}controls.enabled=true;if(canvas.hasPointerCapture(d.id))canvas.releasePointerCapture(d.id);canvas.style.cursor=active?'move':'';}
 function setActive(value){finish();if(value)onActivate();active=!!value&&!!sectors[getSector()].photo;button.textContent=active?'✓ Done positioning':'↔ Move photo';button.setAttribute('aria-pressed',String(active));hint.hidden=!active;canvas.style.cursor=active?'move':'';}
 function sync(){const s=sectors[getSector()];document.querySelector('#photoEditControls').hidden=!s.photo;if(!s.photo){setActive(false);return;}s.photoLayout||=defaultPhotoLayout();for(const [id,key,factor,suffix] of [['photoX','x',100,'%'],['photoY','y',100,'%'],['photoZoom','scale',100,'%'],['photoRotation','rotation',1,'°'],['photoOpacity','opacity',100,'%']]){document.querySelector('#'+id).value=s.photoLayout[key]*factor;document.querySelector('#'+id+'Value').value=Math.round(s.photoLayout[key]*factor)+suffix;}}
 button.onclick=()=>setActive(!active);
 for(const [id,key,factor] of [['photoX','x',100],['photoY','y',100],['photoZoom','scale',100],['photoRotation','rotation',1],['photoOpacity','opacity',100]]){const input=document.querySelector('#'+id);input.onpointerdown=beforeChange;input.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))beforeChange();};input.oninput=e=>{const si=getSector(),s=sectors[si];if(!s.photo)return;s.photoLayout[key]=+e.target.value/factor;renderPhoto(s,defs[si]);sync();};}
 document.querySelector('#resetPhoto').onclick=()=>{const si=getSector(),s=sectors[si];if(!s.photo)return;beforeChange();s.photoLayout=defaultPhotoLayout();renderPhoto(s,defs[si]);sync();};
 canvas.addEventListener('pointerdown',e=>{if(!active||e.button!==0)return;e.preventDefault();e.stopImmediatePropagation();const si=getSector(),p=point(e,si);if(!p||Math.abs(p.x)>sectors[si].width/2||p.y<0||p.y>defs[si].h)return;drag={si,start:p,layout:{...sectors[si].photoLayout},id:e.pointerId,changed:false};controls.enabled=false;canvas.setPointerCapture(e.pointerId);},{capture:true});
 canvas.addEventListener('pointermove',e=>{if(!active)return;e.preventDefault();e.stopImmediatePropagation();if(!drag)return;const d=drag,p=point(e,d.si);if(!p)return;if(!d.changed){beforeChange();d.changed=true;}const s=sectors[d.si];s.photoLayout.x=THREE.MathUtils.clamp(d.layout.x+(p.x-d.start.x)/s.width,-1,1);s.photoLayout.y=THREE.MathUtils.clamp(d.layout.y+(p.y-d.start.y)/defs[d.si].h,-1,1);renderPhoto(s,defs[d.si]);sync();},{capture:true});
 canvas.addEventListener('pointerup',e=>{if(!active)return;e.preventDefault();e.stopImmediatePropagation();finish();},{capture:true});canvas.addEventListener('pointercancel',()=>finish(true));canvas.addEventListener('lostpointercapture',()=>finish(true));window.addEventListener('blur',()=>finish(true));window.addEventListener('keydown',e=>{if(e.key==='Escape'){finish(true);setActive(false);}});
 return{get active(){return active},setActive,sync};
}
